<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Importação e exportação de clientes privados';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_client_imports'.$q);$hidden=function(string $action)use($esc,$company_client_imports_csrf){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_client_imports_csrf" value="'.$esc($company_client_imports_csrf).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';}; ?>
<section class="company-settings-card"><h1>Importação e exportação de clientes privados</h1><p>Crie novas identidades da empresa ativa a partir de um arquivo revisado. Contatos, compartilhamentos, sessões e histórico financeiro permanecem em seus fluxos próprios.</p><?php if($error){?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><p><a href="<?= $esc($url()); ?>">Reabrir a tela</a></p><?php } ?>
<h2>Exportar identidades próprias</h2><p><a id="client-export" href="<?= $esc($url('?export=clients&after='.(int)$client_page['after'])); ?>">Baixar esta página em CSV privado (até 100 clientes)</a></p><p>Inclui ID, nome, CPF/CNPJ e estado ativo de identidades pertencentes à empresa. Não inclui identidades recebidas por compartilhamento, contatos ou documentos financeiros. Nomes com prefixo de fórmula recebem apóstrofo. O CSV de exportação tem colunas de identificação adicionais; para importar novas identidades, use somente o cabeçalho indicado abaixo.</p><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Nome</th><th>CPF/CNPJ</th><th>Estado</th></tr></thead><tbody><?php foreach($client_page['items'] as $row){?><tr><td><?= (int)$row['userid']; ?></td><td><?= $esc($row['company']); ?></td><td><?= $esc($row['vat']); ?></td><td><?= (int)$row['active']===1?'Ativo':'Inativo'; ?></td></tr><?php } ?></tbody></table></div><?php if($client_page['next']!==null){?><a id="client-export-next" href="<?= $esc($url('?after='.$client_page['next'])); ?>">Próxima página de clientes para exportação</a><?php } ?>
<?php if($batch){?><h2>Lote <?= $esc($batch['batch_id']); ?></h2><p>Estado: <?= $batch['state']==='committed'?'Confirmado':($batch['expired']?'Preview expirado':'Aguardando confirmação'); ?> · Válido até <?= $esc($batch['expires_at']); ?> UTC.</p><div class="table-responsive"><table id="client-import-preview" class="table"><thead><tr><th>Linha</th><th>Nome revisado</th><th>CPF/CNPJ revisado</th></tr></thead><tbody><?php foreach($batch['items'] as $index=>$item){?><tr><td><?= $index+1; ?></td><td><?= $esc($item['company']); ?></td><td><?= $esc($item['vat']); ?></td></tr><?php } ?></tbody></table></div>
<?php if($batch['result']){?><p role="status">Lote confirmado. Clientes privados criados:</p><ul><?php foreach($batch['result']['client_ids'] as $id){?><li><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_clients?client='.(int)$id)); ?>">Cliente <?= (int)$id; ?></a></li><?php } ?></ul><?php }elseif(!$batch['expired']&&$can_import){?><?= form_open($url());$hidden('commit'); ?><input type="hidden" name="batch_id" value="<?= $esc($batch['batch_id']); ?>"><input type="hidden" name="revision" value="<?= $esc($batch['revision']); ?>"><p>Revise todas as linhas. CPF/CNPJ e permissões serão revalidados antes de qualquer criação. Se uma linha falhar, o lote inteiro será revertido.</p><button id="client-import-commit" type="submit">Confirmar lote inteiro de clientes privados</button><?= form_close(); ?><?php } ?><?php } ?>
<?php if($can_import){?><h2>Gerar preview obrigatório</h2><p>Até 100 linhas e 256 KiB em UTF-8. CSV com ponto e vírgula e cabeçalho exato; JSON com lista de objetos. Nome é obrigatório; CPF/CNPJ pode ficar vazio conforme a política atual do diretório. CPF/CNPJ em JSON precisa ser texto. Duplicidade de documento, inclusive em outra origem ou no legado, impede o lote sem revelar a identidade em conflito.</p><pre>company;vat</pre><p>Não envie IDs, empresa, contatos, e-mails ou compartilhamentos. Fórmulas e campos desconhecidos são recusados. O preview expira em uma hora e não cria clientes.</p><?= form_open_multipart($url());$hidden('preview'); ?><label for="client-import-format">Formato</label><select id="client-import-format" class="form-control" name="format"><option value="csv">CSV (;)</option><option value="json">JSON</option></select><label for="client-import-file">Arquivo privado</label><input id="client-import-file" class="form-control" type="file" name="source_file" accept=".csv,.json" required><button type="submit">Validar e visualizar antes de importar</button><?= form_close(); ?>
<h2>Seus lotes recentes nesta empresa</h2><ul><?php foreach($batches as $row){?><li><a href="<?= $esc($url('?batch='.$row['batch_id'])); ?>"><?= $esc($row['batch_id']); ?></a> · <?= (int)$row['row_count']; ?> linhas · <?= $esc($row['state']==='committed'?'Confirmado':'Preview'); ?> · <?= $esc($row['created_at']); ?> UTC</li><?php } ?></ul><?php } ?></section>
<?php require APPPATH.'views/admin/companies/layout_tail.php'; ?>
